@using Microsoft.AspNetCore.Components
@using Microsoft.AspNetCore.Components.Routing
@using Microsoft.AspNetCore.Components.Forms
@using Microsoft.AspNetCore.Components.Web
@using static Microsoft.AspNetCore.Components.Web.RenderMode
@using Agentstration.Web.Components

Program.cs:
using NavigationHarness.Components;
var builder = WebApplication.CreateBuilder(args);
builder.Services.AddLocalization(o => o.ResourcesPath = "Resources");
builder.Services.AddRazorComponents().AddInteractiveServerComponents();
var app = builder.Build();
app.UseRequestLocalization(new RequestLocalizationOptions().SetDefaultCulture("en-US").AddSupportedCultures("en-US", "fr-FR").AddSupportedUICultures("en-US", "fr-FR"));
app.UseAntiforgery();
app.MapStaticAssets();
app.MapRazorComponents<App>().AddInteractiveServerRenderMode();
app.Run();

Pages/Specimen.razor:
@page "/navigation"
@inject NavigationManager Navigation
<PageTitle>Resource navigation component fixture</PageTitle>
@if (!new Uri(Navigation.Uri).Query.Contains("guard=false")) { <UnsavedNavigationGuard IsDirty="@(Draft.Length > 0 || Yaml.Length > 0)" ViewQueryParameters="@(new[] { "view", "tab" })" /> }
<div data-theme="@(new Uri(Navigation.Uri).Query.Contains("theme=dark") ? "dark" : "light")" class="fixture-root app-shell @(new Uri(Navigation.Uri).Query.Contains("theme=dark") ? "theme-dark" : "theme-light")">
<h1>@(French ? "Spécimen du composant de navigation" : "Navigation component specimen")</h1><p>@(French ? "Hôte de test isolé — aucune donnée Agent." : "Isolated test host — no Agent data.")</p>
<div class="fixture">
<div class="fixture-nav"><ResourceNavigation Items="Items" DefaultPath="overview" SelectionChanged="value => selected = value" /></div>
<main><p id="selected">@selected</p><p id="initializations">@initializations</p>
<section hidden="@(selected != "overview")"><h2>@(French ? "Vue d’ensemble" : "Overview")</h2></section>
<section hidden="@(selected != "definition/tools")"><h2>@(French ? "Outils" : "Tools")</h2><EditForm Model="this" class="form-grid"><FormField Label="@(French ? "Brouillon formulaire" : "Form draft")"><ClearableText @bind-Value="Draft" /></FormField></EditForm></section>
<section hidden="@(selected != "yaml")"><h2>YAML</h2><EditForm Model="this" class="form-grid"><FormField Label="@(French ? "Brouillon YAML" : "YAML draft")"><ClearableText Multiline @bind-Value="Yaml" /></FormField></EditForm></section>
</main></div></div>
<style>
.fixture-root{--surface:var(--color-surface);--border:var(--color-border);--text:var(--color-text-primary);--muted:var(--color-text-muted);--primary:var(--color-action-primary);--primary-soft:var(--color-action-primary-soft)}body{margin:0;font-family:var(--font-family-sans)}.fixture-root{box-sizing:border-box;padding:2rem;min-height:100dvh;background:var(--color-background-app);color:var(--text)}h1{font-size:1.6rem}.fixture{display:grid;grid-template-columns:minmax(0,1fr) 18rem;gap:1.5rem}.fixture-nav{grid-column:2;grid-row:1}main{grid-column:1;grid-row:1;min-width:0;padding:1.5rem;border:1px solid var(--border);border-radius:.75rem;background:var(--surface)}#initializations{font-size:.8rem;color:var(--muted)}@@media(max-width:899px){.fixture-root{padding:1rem}.fixture{display:flex;flex-direction:column}main{padding:1rem}}
</style>
@code{
 string? selected; public string Draft{get;set;}="";public string Yaml{get;set;}="";int initializations;
 bool French=>System.Globalization.CultureInfo.CurrentUICulture.Name=="fr-FR";
 protected override void OnInitialized()=>initializations++;
 IReadOnlyList<ResourceNavigationItem> Items=>[
 new("overview",French?"Vue d’ensemble":"Overview","home"),
 new("definition",French?"Définition":"Definition","settings"){Navigable=false},
 new("definition/tools",French?"Outils":"Tools","tool"),
 new("definition/model",French?"Modèle et exécution — libellé autorisé volontairement très long":"Model and execution — deliberately long authorized label","cpu"),
 new("definition/secret","Confidential hidden label","lock"){Visible=false},
 new("access",French?"Accès":"Access","key"){Enabled=false},
 new("yaml","YAML","code")];
}
